import "./features.css";

export interface FeatureCard {
  eyebrow: string;
  title: string;
  body: string;
}
export interface FeatureCardsProps {
  subtitle: string;
  heading: string;
  cards: FeatureCard[];
  columns: "2" | "3" | "4";
  colorScheme: "brand mix" | "light" | "purple" | "dark" | "outline";
  corners: "sharp" | "soft" | "round";
  depth: "flat" | "subtle" | "raised";
  cardAlign: "left" | "center";
  sectionBg: "light" | "white" | "dark" | "none";
}

function cardScheme(colorScheme: FeatureCardsProps["colorScheme"], i: number): string {
  if (colorScheme === "brand mix") {
    const cycle: string[] = ["primary", "light", "dark"];
    return cycle[i % 3] ?? "light";
  }
  if (colorScheme === "purple") return "primary";
  return colorScheme;
}

export function FeatureCardsRender({
  subtitle,
  heading,
  cards,
  columns,
  colorScheme,
  corners,
  depth,
  cardAlign,
  sectionBg,
}: FeatureCardsProps) {
  const list = cards || [];
  const cols = Math.min(Number(columns) || 3, list.length || 1);
  return (
    <div className="p1-feature-cards p1-block" data-bg={sectionBg} data-align={cardAlign}>
      <div className="p1-feature-cards__inner">
        {(subtitle || heading) && (
          <div className="p1-feature-cards__header">
            {subtitle && <p className="p1-feature-cards__subtitle" data-bg={sectionBg}>{subtitle}</p>}
            {heading && <h2 className="p1-feature-cards__heading">{heading}</h2>}
          </div>
        )}
        <div
          className="p1-feature-cards__grid"
          style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
        >
          {list.map((c, i) => (
            <div
              key={i}
              className="p1-feature-cards__card"
              data-scheme={cardScheme(colorScheme, i)}
              data-corners={corners}
              data-depth={depth}
            >
              {c.eyebrow && <div className="p1-feature-cards__eyebrow">{c.eyebrow}</div>}
              <h3 className="p1-feature-cards__card-title">{c.title}</h3>
              <p className="p1-feature-cards__card-body">{c.body}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { FeatureCardsRender, type FeatureCardsProps, type FeatureCard } from "./features";
export type { FeatureCardsProps, FeatureCard };

export const FeatureCardsBlock: ComponentConfig<FeatureCardsProps> = {
  fields: {
    subtitle: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short eyebrow / section label above the heading. 3–6 words, italic feel." },
    },
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Section heading. Bold claim, under 10 words." },
    },
    cards: {
      type: "array" as const,
      arrayFields: {
        eyebrow: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "1–2 word label for this card. Title case." },
        },
        title: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Card title. 3–5 words." },
        },
        body: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "1–2 sentence description of this feature." },
        },
      },
      defaultItemProps: { eyebrow: "Eyebrow", title: "Feature", body: "Describe the feature." },
      getItemSummary: (item: FeatureCard) => item.title || "Card",
    },
    columns: {
      type: "select" as const,
      options: [
        { label: "2", value: "2" },
        { label: "3", value: "3" },
        { label: "4", value: "4" },
      ],
    },
    colorScheme: {
      type: "select" as const,
      options: [
        { label: "Brand mix", value: "brand mix" },
        { label: "Light", value: "light" },
        { label: "Purple", value: "purple" },
        { label: "Dark", value: "dark" },
        { label: "Outline", value: "outline" },
      ],
    },
    corners: {
      type: "select" as const,
      options: [
        { label: "Sharp", value: "sharp" },
        { label: "Soft", value: "soft" },
        { label: "Round", value: "round" },
      ],
    },
    depth: {
      type: "select" as const,
      options: [
        { label: "Flat", value: "flat" },
        { label: "Subtle", value: "subtle" },
        { label: "Raised", value: "raised" },
      ],
    },
    cardAlign: {
      type: "radio" as const,
      options: [
        { label: "Left", value: "left" },
        { label: "Center", value: "center" },
      ],
    },
    sectionBg: {
      type: "select" as const,
      options: [
        { label: "Light", value: "light" },
        { label: "White", value: "white" },
        { label: "Dark", value: "dark" },
        { label: "None", value: "none" },
      ],
    },
  },
  defaultProps: {
    subtitle: "Why teams choose us",
    heading: "Everything you need, in one place.",
    cards: [
      { eyebrow: "Simple", title: "Easy to use", body: "A visual editor anyone on your team can pick up in minutes — no training required." },
      { eyebrow: "Flexible", title: "Built to scale", body: "Start with one page and grow to hundreds — everything stays consistent as you go." },
      { eyebrow: "Reliable", title: "Always on", body: "Fast, secure, and dependable — so you can focus on your content, not your infrastructure." },
    ],
    columns: "3",
    colorScheme: "brand mix",
    corners: "round",
    depth: "flat",
    cardAlign: "left",
    sectionBg: "light",
  },
  render: FeatureCardsRender,
};

export const meta = defineMeta({
  title: 'Feature Cards',
  description: 'Grid of 2–4 feature cards each with eyebrow, title, and body in multiple color schemes and card styles; use for feature lists or benefit grids.',
  categories: ["value"],
  published: true,
});

/* Section background */
.p1-feature-cards[data-bg="light"] { background-color: var(--p1-surface-subtle); }
.p1-feature-cards[data-bg="white"] { background-color: var(--p1-surface-default); }
.p1-feature-cards[data-bg="dark"] { background-color: var(--p1-surface-inverse); color: var(--p1-fg-inverse); }

.p1-feature-cards__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}

.p1-feature-cards__header {
  margin-block-end: var(--p1-space-xl);
  text-align: center;
}
.p1-feature-cards__subtitle {
  color: var(--p1-accent);
  font-style: italic;
  font-size: var(--p1-text-xl);
  margin-block-end: var(--p1-space-xs);
}
.p1-feature-cards__subtitle[data-bg="dark"] { color: var(--p1-warning); }

.p1-feature-cards__heading {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-feature-cards__heading { font-size: var(--p1-text-3xl); }
}

.p1-feature-cards__grid {
  display: grid;
  gap: var(--p1-space-md);
  grid-template-columns: 1fr;
}
@media (width < 40rem) {
  .p1-feature-cards__grid { grid-template-columns: 1fr !important; }
}

/* Card */
.p1-feature-cards__card {
  display: flex;
  flex-direction: column;
  gap: var(--p1-space-sm);
  min-block-size: 15rem;
  padding: var(--p1-space-lg);
}
.p1-feature-cards[data-align="center"] .p1-feature-cards__card {
  align-items: center;
  text-align: center;
}

/* Card schemes */
.p1-feature-cards__card[data-scheme="primary"] {
  background-color: var(--p1-accent);
  color: var(--p1-fg-inverse);
}
.p1-feature-cards__card[data-scheme="primary"] .p1-feature-cards__eyebrow { color: var(--p1-warning); }
.p1-feature-cards__card[data-scheme="primary"] .p1-feature-cards__card-body { color: var(--p1-fg-inverse-faint); }

.p1-feature-cards__card[data-scheme="light"] {
  background-color: var(--p1-surface-default);
  border: 1px solid var(--p1-border);
  color: var(--p1-fg-default);
}
.p1-feature-cards__card[data-scheme="light"] .p1-feature-cards__eyebrow { color: var(--p1-accent); }
.p1-feature-cards__card[data-scheme="light"] .p1-feature-cards__card-body { color: var(--p1-fg-muted); }

.p1-feature-cards__card[data-scheme="dark"] {
  background-color: var(--p1-surface-inverse);
  color: var(--p1-fg-inverse);
}
.p1-feature-cards__card[data-scheme="dark"] .p1-feature-cards__eyebrow { color: var(--p1-warning); }
.p1-feature-cards__card[data-scheme="dark"] .p1-feature-cards__card-body { color: var(--p1-fg-inverse-subtle); }

.p1-feature-cards__card[data-scheme="outline"] {
  background-color: transparent;
  border: 1.5px solid var(--p1-border-strong);
  color: var(--p1-fg-default);
}
.p1-feature-cards__card[data-scheme="outline"] .p1-feature-cards__eyebrow { color: var(--p1-accent); }
.p1-feature-cards__card[data-scheme="outline"] .p1-feature-cards__card-body { color: var(--p1-fg-muted); }

/* Corners */
.p1-feature-cards__card[data-corners="sharp"] { border-radius: var(--p1-radius-card); }
.p1-feature-cards__card[data-corners="soft"] { border-radius: var(--p1-radius-xl); }
.p1-feature-cards__card[data-corners="round"] { border-radius: 2.5rem; }

/* Depth */
.p1-feature-cards__card[data-depth="subtle"] { box-shadow: var(--p1-shadow-md); }
.p1-feature-cards__card[data-depth="raised"] { box-shadow: var(--p1-shadow-lg); }

.p1-feature-cards__eyebrow {
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.p1-feature-cards__card-title {
  font-size: var(--p1-text-xl);
  font-weight: var(--p1-weight-bold);
  line-height: var(--p1-leading-tight);
}
.p1-feature-cards__card-body {
  font-size: 0.9375rem;
  line-height: var(--p1-leading-normal);
}

